import {useMutation} from '@github-ui/react-query'
import {useNavigate} from '@github-ui/use-navigate'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

import {publicMonitoringSettingsPath} from '../paths'

interface UpdatePublicMonitoringResponse {
  success?: boolean
  error_message?: string
}

const DEFAULT_ERROR = 'Something went wrong, please try again.'

export function useEnablePublicMonitoringMutation({
  enterpriseSlug,
  onSuccess,
}: {
  enterpriseSlug: string
  onSuccess?: () => void | Promise<void>
}) {
  const navigate = useNavigate()

  return useMutation({
    mutationFn: async () => {
      const result = await verifiedFetchJSON(publicMonitoringSettingsPath({enterpriseSlug}), {
        method: 'PUT',
        body: {secret_scanning_public_monitoring: 'enabled'},
      })
      if (!result.ok) {
        throw new Error(DEFAULT_ERROR)
      }
      const data: UpdatePublicMonitoringResponse = await result.json()
      if (!data?.success) {
        throw new Error(data?.error_message ?? DEFAULT_ERROR)
      }
    },
    onSuccess: async () => {
      await onSuccess?.()
      navigate(window.location.pathname)
    },
  })
}
