import {mainQuery} from '@github-ui/react-core/future/main-query'
import {publicMonitoringAppBuilder} from '../config/app-builder'

import type {PublicMonitoringPayload} from '../types'

export const businessPublicMonitoringRoute = publicMonitoringAppBuilder.createQueryRouteConfig(
  'businessPublicMonitoringRoute',
  {
    path: '/enterprises/:slug/security/public-monitoring',
    queries: [
      mainQuery<PublicMonitoringPayload>({
        staleTimeForNavigation: Infinity,
        queryDeps: ({pathname, searchParams}) => ({pathname, searchParams: searchParams.toString()}),
      }),
    ],
  },
)
