import {
  CloudIcon,
  CommentIcon,
  CreditCardIcon,
  DatabaseIcon,
  GlobeIcon,
  KeyIcon,
  MarkGithubIcon,
  SparkleIcon,
} from '@primer/octicons-react'

import {TOKENS_BY_CATEGORY} from './secret-category-tokens'

export const SECRET_CATEGORY_ICON = {
  GitHub: {icon: MarkGithubIcon, description: 'GitHub token'},
  Cloud: {icon: CloudIcon, description: 'Cloud service provider secret'},
  AI: {icon: SparkleIcon, description: 'AI provider secret'},
  Database: {icon: DatabaseIcon, description: 'Database secret'},
  Payment: {icon: CreditCardIcon, description: 'Payment platform secret'},
  Messaging: {icon: CommentIcon, description: 'Messaging secret'},
  Webhook: {icon: GlobeIcon, description: 'Webhook URL'},
  Other: {icon: KeyIcon, description: 'Secret'},
}

export type SecretCategory = keyof typeof SECRET_CATEGORY_ICON

const categoryEntries = Object.entries(TOKENS_BY_CATEGORY) as Array<[SecretCategory, readonly string[]]>

const CATEGORY_BY_TOKEN: ReadonlyMap<string, SecretCategory> = new Map(
  categoryEntries.flatMap(([category, tokens]) => tokens.map(token => [token.toLowerCase(), category])),
)

export const getSecretCategory = (slug: string): SecretCategory => CATEGORY_BY_TOKEN.get(slug.toLowerCase()) ?? 'Other'
