export function publicMonitoringAlertDetailPath({
  enterpriseSlug,
  alertKey,
  page,
}: {
  enterpriseSlug: string
  alertKey: string
  page: number
}) {
  return `/enterprises/${enterpriseSlug}/security/public-monitoring/${alertKey}?page=${page}`
}

export function publicMonitoringSettingsPath({enterpriseSlug}: {enterpriseSlug: string}) {
  return `/enterprises/${enterpriseSlug}/settings/security_analysis/public_monitoring`
}
