import type {RefObject} from 'react'
import {useState} from 'react'
import {Button, Link, RelativeTime, Spinner} from '@primer/react'
import {ChevronLeftIcon, ChevronRightIcon} from '@primer/octicons-react'
import {UnderlinePanels} from '@primer/react/experimental'
import {SidePanel} from '@github-ui/side-panel'
import {useQuery} from '@github-ui/react-query'
import {ssrSafeDocument, ssrSafeWindow} from '@github-ui/ssr-utils'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {AlertDetailResponse, AlertLocation, PublicMonitoringAlert} from '../types'
import {AttributionMethod, normalizeAttributionMethod, isCodeLocation, getContentLocationUrl} from '../types'
import {publicMonitoringAlertDetailPath} from '../paths'
import {DetailMetadataTable} from './DetailMetadataTable'
import {RecommendationsCard} from './RecommendationsCard'
import {BlobLocationCard} from './shared/BlobLocationCard'
import {ContentLocationCard} from './shared/ContentLocationCard'
import type {BlobLocationCardLocation} from './shared/types'
import {VerifiedDomainBanner} from './VerifiedDomainBanner'
import styles from './AlertDetailPanel.module.css'

interface AlertDetailPanelProps {
  alert: PublicMonitoringAlert
  onClose: () => void
  returnFocusRef: RefObject<HTMLElement | null>
  ownerName: string
  verifiedDomains: string[]
}

export function AlertDetailPanel({alert, onClose, returnFocusRef, ownerName, verifiedDomains}: AlertDetailPanelProps) {
  const [activeTab, setActiveTab] = useState<'details' | 'recommendations'>('details')
  const [locationPage, setLocationPage] = useState(1)

  const [topOffset] = useState(() => {
    const {offsetTop = 0} = ssrSafeDocument?.querySelector('main') || {}
    const {scrollY = 0} = ssrSafeWindow || {}

    if (scrollY >= offsetTop) return 0
    return offsetTop - scrollY
  })

  function handleClose() {
    setActiveTab('details')
    setLocationPage(1)
    onClose()
  }

  return (
    <SidePanel
      open
      topOffset={topOffset}
      onClose={handleClose}
      returnFocusRef={returnFocusRef}
      width="min(90%, 600px)"
      aria-label={`Alert details: ${alert.secretTypeLabel}`}
    >
      <SidePanel.Heading>
        <div className="tmp-py-3 tmp-px-4">
          <h2 className="f3 text-bold tmp-m-0">{alert.secretTypeLabel}</h2>
          <p className="f6 color-fg-muted tmp-m-0 tmp-mt-1">
            detected on{' '}
            <RelativeTime datetime={alert.createdAt} format="datetime" day="numeric" month="long" year="numeric" /> · in{' '}
            {/* repositoryName is NWO format from backend, safe to use directly in href */}
            <Link href={`/${alert.repositoryName}`} muted>
              {alert.repositoryName}
            </Link>
          </p>
        </div>
      </SidePanel.Heading>

      <hr className="tmp-mt-0 tmp-mb-2" />

      <UnderlinePanels aria-label="Alert detail tabs" className={styles.PanelTabs}>
        <UnderlinePanels.Tab aria-selected={activeTab === 'details'} onSelect={() => setActiveTab('details')}>
          Details
        </UnderlinePanels.Tab>
        <UnderlinePanels.Tab
          aria-selected={activeTab === 'recommendations'}
          onSelect={() => setActiveTab('recommendations')}
        >
          Recommendations
        </UnderlinePanels.Tab>

        <UnderlinePanels.Panel hidden={activeTab !== 'details'} className="tmp-pt-3 tmp-px-4 overflow-hidden">
          <DetailsTab
            alert={alert}
            ownerName={ownerName}
            page={locationPage}
            onPageChange={setLocationPage}
            verifiedDomains={verifiedDomains}
          />
        </UnderlinePanels.Panel>

        <UnderlinePanels.Panel hidden={activeTab !== 'recommendations'} className="tmp-pt-3 tmp-px-4 overflow-hidden">
          <RecommendationsCard />
        </UnderlinePanels.Panel>
      </UnderlinePanels>
    </SidePanel>
  )
}

function DetailsTab({
  alert,
  ownerName,
  page,
  onPageChange,
  verifiedDomains,
}: {
  alert: PublicMonitoringAlert
  ownerName: string
  page: number
  onPageChange: (page: number) => void
  verifiedDomains: string[]
}) {
  const showVerifiedDomainBanner =
    normalizeAttributionMethod(alert.attributionMethod) === AttributionMethod.VerifiedDomain

  const {data, isLoading, isError} = useQuery<AlertDetailResponse>({
    queryKey: ['secret-scanning', 'public-monitoring', 'alert-detail', ownerName, alert.alertKey, page],
    queryFn: async () => {
      const url = publicMonitoringAlertDetailPath({
        enterpriseSlug: ownerName,
        alertKey: alert.alertKey,
        page,
      })
      const response = await reactFetchJSON(url, {method: 'GET'})
      if (!response.ok) throw new Error(`Failed to fetch alert details: ${response.status}`)
      return response.json()
    },
  })

  const totalPages =
    data?.totalLocationsCount !== undefined && data?.locationsPerPage
      ? Math.ceil(data.totalLocationsCount / data.locationsPerPage)
      : undefined
  const hasPrev = page > 1
  const hasNext = totalPages !== undefined && page < totalPages

  return (
    <>
      {showVerifiedDomainBanner && <VerifiedDomainBanner verifiedDomains={verifiedDomains} />}

      <DetailMetadataTable
        alert={alert}
        commitAuthorEmail={data?.commitAuthorEmail ?? null}
        committedAt={data?.committedAt ?? null}
      />

      <h3 className="f5 text-bold tmp-mt-3 tmp-mb-2 tmp-pb-1">
        {data?.totalLocationsCount !== undefined
          ? `Detected in ${data.totalLocationsCount} location${data.totalLocationsCount !== 1 ? 's' : ''} outside the enterprise`
          : 'Locations'}
      </h3>

      {isLoading ? (
        <div className="d-flex flex-justify-center tmp-py-4">
          <Spinner size="medium" />
        </div>
      ) : isError ? (
        <p className="color-fg-danger f5">Failed to load location details. Please try again later.</p>
      ) : data?.locations && data.locations.length > 0 ? (
        <div>
          {data.locations.map(location =>
            isCodeLocation(location.contentType) ? (
              <BlobLocationCard
                key={`${location.commitOid}-${location.path}`}
                location={toBlobLocationCardLocation(location)}
                ownerName={data.repositoryOwner ?? ''}
                repoName={data.repositoryName ?? ''}
              />
            ) : (
              <ContentLocationCard
                key={`content-${location.contentType}-${location.contentNumber ?? ''}-${location.contentId ?? ''}`}
                contentType={location.contentType}
                contentNumber={location.contentNumber}
                url={getContentLocationUrl({
                  owner: data.repositoryOwner,
                  repo: data.repositoryName,
                  contentType: location.contentType,
                  contentNumber: location.contentNumber,
                  contentId: location.contentId,
                })}
              />
            ),
          )}
          {(hasPrev || hasNext) && (
            <div className="d-flex flex-justify-center gap-2 tmp-py-2">
              <Button
                variant="invisible"
                className={hasPrev ? 'fgColor-accent' : ''}
                leadingVisual={ChevronLeftIcon}
                disabled={!hasPrev}
                onClick={() => onPageChange(page - 1)}
              >
                Previous
              </Button>
              <Button
                variant="invisible"
                className={hasNext ? 'fgColor-accent' : ''}
                trailingVisual={ChevronRightIcon}
                disabled={!hasNext}
                onClick={() => onPageChange(page + 1)}
              >
                Next
              </Button>
            </div>
          )}
        </div>
      ) : (
        <p className="color-fg-muted f5">No location data available.</p>
      )}
    </>
  )
}

/** Maps our AlertLocation into the generic BlobLocationCardLocation shape. */
function toBlobLocationCardLocation(loc: AlertLocation): BlobLocationCardLocation {
  return {
    path: loc.path,
    commitOid: loc.commitOid,
    startLine: loc.startLine,
    endLine: loc.endLine,
    startColumn: loc.startColumn,
    endColumn: loc.endColumn,
    contentType: loc.contentType,
    foundInArchive: loc.foundInArchive,
    commitMessage: loc.commitMessage,
    commitCreatedAt: loc.commitCreatedAt,
    commitAuthorAvatarUrl: loc.commitAuthorAvatarUrl,
    blobLines: loc.blob?.lines,
    blobLanguage: loc.blob?.language,
    blobIsTruncated: loc.blob?.isTruncated,
    blobIsText: loc.blob?.isText,
  }
}
